const posts = [{"id":"W01-D01","sequence":1,"pillar":"تعريف بالعلامة","title":"هنا يأتي دور القنّاص","hook":"كل يوم تظهر عشرات أدوات الذكاء الاصطناعي… لكن من يملك الوقت لتجربتها كلها؟","narration":"كل يوم تظهر عشرات أدوات الذكاء الاصطناعي، وكل واحدة تقول إنها ستغيّر حياتك. لكن من يملك الوقت ليجرّبها كلها؟ هنا يأتي دور القناص. في سنايبر تونس نبحث، نجرّب، ونقارن، ثم نقدّم لك الأدوات والأفكار التي تستحق وقتك، في فيديوهات قصيرة وواضحة. من صناعة الصور والفيديو، إلى الدراسة والعمل وصناعة المحتوى. هدفنا بسيط: أن نضع مستقبل الذكاء الاصطناعي بين يديك. تابع الصفحة، واكتب في التعليقات: ما أول مهمة تريد أن ينجزها لك الذكاء الاصطناعي؟","caption":"كل يوم تظهر عشرات أدوات الذكاء الاصطناعي، لكن ليس كل ما يظهر يستحق وقتك. في Sniper‑Tn نبحث، نجرّب ونقارن، ثم نقدّم لك أقوى الأدوات والأفكار في فيديوهات قصيرة وواضحة. تابع الصفحة واكتب: ما أول مهمة تريد من الذكاء الاصطناعي أن ينجزها لك؟","pinnedComment":"🎯 ما المشكلة أو المهمة التي تريد أن نختبر لها أداة ذكاء اصطناعي؟ سنختار أفضل اقتراح لفيديو قادم.","hashtags":["#الذكاء_الاصطناعي","#أدوات_الذكاء_الاصطناعي","#تقنية","#AI","#SniperTN"],"durationSeconds":46.368},{"id":"W01-D02","sequence":2,"pillar":"مهارات الـPrompt","title":"قاعدة القنّاص لكتابة Prompt قوي","hook":"إذا كانت إجابة الذكاء الاصطناعي عامة ومملّة، فالمشكلة غالبًا في طريقة طلبك.","narration":"إذا كانت إجابات الذكاء الاصطناعي عامة ومملّة، فالمشكلة غالبًا في طريقة طلبك. استعمل قاعدة القنّاص من ثلاثة أجزاء: الهدف، والسياق، وشكل النتيجة. بدل أن تقول: اكتب لي منشورًا؛ قل: اكتب منشور فيسبوك من ثمانين كلمة، موجّهًا للمبتدئين، يشرح فائدة الذكاء الاصطناعي بنبرة حماسية وينتهي بسؤال. كلّما كان طلبك أدق، كانت النتيجة أقوى. احفظ هذه القاعدة وجرّبها اليوم.","caption":"🎯 قاعدة Prompt بسيطة تغيّر جودة النتيجة: الهدف + السياق + شكل النتيجة. بدل الطلب العام، حدّد لمن تكتب، ماذا تريد، وبأي طول ونبرة. احفظ المنشور وجرّب الصيغة اليوم.","pinnedComment":"اكتب Prompt تستعمله حاليًا، وسنساعدك على جعله أدق في فيديو قادم.","hashtags":["#برومبت","#Prompt","#الذكاء_الاصطناعي","#صناعة_المحتوى","#SniperTN"],"durationSeconds":35.616},{"id":"W01-D03","sequence":3,"pillar":"استخدام عملي","title":"3 مهام يومية سلّمها للذكاء الاصطناعي","hook":"ثلاث مهام متكررة يمكن للذكاء الاصطناعي أن يختصرها عليك اليوم.","narration":"ثلاث مهام يومية يمكن للذكاء الاصطناعي أن يختصرها عليك. الأولى: تلخيص نص طويل إلى خمس نقاط واضحة. الثانية: تحويل فكرة مبعثرة إلى خطة خطوة بخطوة. الثالثة: إعادة صياغة رسالة لتصبح أقصر وأكثر احترافية. أعطه الهدف والسياق، واطلب شكل النتيجة بوضوح، ثم راجع ما كتبه قبل الاستعمال. ابدأ بمهمة واحدة فقط، وقِس كم دقيقة وفّرت عليك. أيّ مهمة ستجرّب أولًا؟","caption":"لا تبدأ بعشرة أدوات. اختر مهمة واحدة متكررة: تلخيص، تخطيط أو إعادة صياغة. جرّبها اليوم، راجع النتيجة، ثم احسب الوقت الذي وفّرته.","pinnedComment":"1 تلخيص، 2 تخطيط، أم 3 إعادة صياغة؟ اكتب الرقم في التعليقات.","hashtags":["#إنتاجية","#الذكاء_الاصطناعي","#AI","#نصائح_تقنية","#SniperTN"],"durationSeconds":35.616},{"id":"W01-D04","sequence":4,"pillar":"وعي وتحقق","title":"لا تصدّق كل إجابة من الذكاء الاصطناعي","hook":"الذكاء الاصطناعي قد يجيبك بثقة… وهو مخطئ.","narration":"تنبيه: الذكاء الاصطناعي قد يجيبك بثقة وهو مخطئ. قبل أن تعتمد أي معلومة، طبّق اختبار القنّاص: اطلب المصدر والرابط، تحقّق من تاريخ النشر، وقارن المعلومة بمصدر مستقل. وإذا كان الموضوع طبيًا أو قانونيًا أو ماليًا، لا تتخذ قرارًا اعتمادًا على جواب آلي وحده. الذكاء الاصطناعي مساعد سريع، لكنه ليس بديلًا عن التحقق والخبرة. أرسل هذا الفيديو لشخص يصدّق كل ما يقوله الذكاء الاصطناعي.","caption":"قبل اعتماد أي معلومة من AI: اطلب المصدر، تحقّق من التاريخ، وقارن بمصدر مستقل. وفي القرارات الطبية أو القانونية أو المالية، ارجع دائمًا إلى مختص.","pinnedComment":"هل سبق أن أعطاك الذكاء الاصطناعي معلومة بدت صحيحة ثم اكتشفت أنها خاطئة؟","hashtags":["#تحقق","#وعي_رقمي","#الذكاء_الاصطناعي","#AI","#SniperTN"],"durationSeconds":39.648},{"id":"W01-D05","sequence":5,"pillar":"خصوصية وأمان","title":"قبل أن ترفع ملفك إلى أداة AI","hook":"ملف واحد قد يحتوي معلومات أكثر مما تتخيّل.","narration":"قبل أن ترفع أي ملف إلى أداة ذكاء اصطناعي، توقّف عشر ثوانٍ. احذف الأسماء، والعناوين، وأرقام الهوية، وكلمات المرور، وبيانات العملاء. استبدل التفاصيل الحساسة بأسماء وهمية، وراجع إعدادات الخصوصية وسياسة الخدمة. وإذا كان الملف سريًا أو تابعًا للعمل، فلا ترفعه قبل الحصول على إذن واضح. الذكاء الاصطناعي يوفّر الوقت، لكن السرعة لا تستحق كشف معلومة حساسة. احفظ هذا التنبيه وشاركه مع فريقك.","caption":"قاعدة بسيطة: إذا لم تكن مستعدًا لنشر المعلومة، فلا تضعها في أداة AI قبل فهم إعدادات الخصوصية والحصول على الإذن المطلوب.","pinnedComment":"احفظ الفيديو وأرسله لأي شخص يستعمل أدوات AI مع ملفات العمل.","hashtags":["#خصوصية","#أمن_رقمي","#الذكاء_الاصطناعي","#حماية_البيانات","#SniperTN"],"durationSeconds":37.8},{"id":"W01-D06","sequence":6,"pillar":"تعلم بالذكاء الاصطناعي","title":"حوّل AI إلى مدرّب شخصي","hook":"لا تطلب شرحًا فقط… اطلب دورة تعلم كاملة في Prompt واحد.","narration":"تريد أن تتعلّم أي موضوع بسرعة؟ لا تطلب شرحًا فقط. قل للذكاء الاصطناعي: اشرح لي الفكرة كأنني مبتدئ، وأعطني مثالًا من الحياة، ثم اختبرني بخمسة أسئلة، وبعد إجابتي اشرح أخطائي واقترح تمرينًا أصعب. بهذه الطريقة يتحوّل من محرّك إجابات إلى مدرّب يتفاعل مع مستواك. لكن تذكّر أن تراجع المراجع، خصوصًا في المعلومات المتخصصة. احفظ هذا الـPrompt، واكتب الموضوع الذي تريد أن تتعلّمه.","caption":"Prompt التعلم: شرح بسيط + مثال واقعي + اختبار + تصحيح + تمرين أصعب. انسخه وجرّبه مع موضوع تعمل على تعلمه حاليًا.","pinnedComment":"اكتب اسم الموضوع فقط، وسنقترح لك Prompt تعلّم مناسبًا.","hashtags":["#تعلم","#دراسة","#Prompt","#الذكاء_الاصطناعي","#SniperTN"],"durationSeconds":36.408},{"id":"W01-D07","sequence":7,"pillar":"تفاعل مجتمعي","title":"تحدّي القنّاص الأول","hook":"أعطنا مهمتك المتكررة… ونحن نبحث لها عن طريقة أذكى.","narration":"هذا هو تحدّي القنّاص الأول. اكتب في التعليقات مهمة تتكرر عندك كل يوم وتستهلك وقتك، من دون مشاركة أي بيانات خاصة. سنختار ثلاثة تعليقات، ونجرّب لكل مهمة طريقة عملية باستعمال الذكاء الاصطناعي، ثم ننشر النتيجة والخطوات والوقت الذي تم توفيره. قد تكون كتابة رسالة، أو ترتيب أفكار، أو تلخيص محتوى، أو أي مهمة أخرى. دورك الآن: اكتب المهمة في جملة واحدة، وتابع الصفحة لترى التجربة.","caption":"🎯 تحدّي القنّاص: اكتب مهمة تتكرر يوميًا وتستهلك وقتك، دون أي بيانات خاصة. سنختار 3 تعليقات ونجرّب لها حلولًا عملية بالذكاء الاصطناعي.","pinnedComment":"الشروط: مهمة واضحة في جملة واحدة، دون أسماء أو ملفات أو معلومات شخصية.","hashtags":["#تحدي_القناص","#مجتمع_الذكاء_الاصطناعي","#إنتاجية","#AI","#SniperTN"],"durationSeconds":40.152}];
const state = $getWorkflowStaticData('global');
if (!Number.isInteger(state.nextIndex) || state.nextIndex < 0 || state.nextIndex >= posts.length) {
  state.nextIndex = 0;
}
const post = posts[state.nextIndex];
const day = String(post.sequence).padStart(2, '0');
const hashtagsText = post.hashtags.join(' ');
const videoUrl = `${config.assetBaseUrl}/day-${day}/reel.mp4`;
const thumbnailUrl = `${config.assetBaseUrl}/day-${day}/thumbnail.jpg`;
const approvalMessage = [
  `مراجعة المحتوى ${post.id}`,
  `العنوان: ${post.title}`,
  `المحور: ${post.pillar}`,
  '',
  'نص التعليق الصوتي:',
  post.narration,
  '',
  'نص منشور فيسبوك:',
  post.caption,
  '',
  `التعليق المثبّت: ${post.pinnedComment}`,
  '',
  config.facebookAutoPublish
    ? 'بالضغط على اعتماد، توافق على نشر هذا الـReel علنًا على صفحة Facebook.'
    : 'النشر الآلي معطّل حاليًا؛ الاعتماد سينقله إلى قائمة الجاهز للنشر.'
].join('\n');
return [{ json: { ...config, ...post, hashtagsText, videoUrl, thumbnailUrl, approvalMessage, queueIndex: state.nextIndex } }];

const content = $('Load Next Content').item.json;
const state = $getWorkflowStaticData('global');
const current = Number.isInteger(content.queueIndex) ? content.queueIndex : 0;
state.nextIndex = (current + 1) % 7;
state.lastApproved = {
  id: content.id,
  approvedAt: new Date().toISOString(),
  facebookAutoPublish: content.facebookAutoPublish,
};
return [{ json: { ...content, status: 'approved', nextQueueIndex: state.nextIndex, metaResult: $input.first().json } }];

